def apply(inputs,premises):
    spans=inputs.get('source_spans',[])
    queries=[]
    i=0
    while i<len(spans):
        span=spans[i]
        text_value=normalized_text(span.get('text',''))
        if is_disclosure_permission_candidate(text_value):
            focus_id=span.get('id')
            definition_id=None
            j=0
            while j<i:
                prior=spans[j]
                prior_text=normalized_text(prior.get('text',''))
                if is_recipient_definition(prior_text):
                    definition_id=prior.get('id')
                j+=1
            unit_ids=[]
            if definition_id is not None and definition_id!=focus_id:
                unit_ids.append(definition_id)
            unit_ids.append(focus_id)
            suffix=str(focus_id)
            queries.append({'id':'recipient_class_'+suffix,'operation':'authorized_recipient_class','unit_ids':unit_ids})
            queries.append({'id':'safeguards_'+suffix,'operation':'disclosure_safeguards','unit_ids':unit_ids})
        i+=1
    return {'queries':queries}

def normalized_text(x):
    if not isinstance(x,str):
        x=str(x)
    return x.casefold().strip()

def has_any_phrase(t,phrases):
    for p in phrases:
        if p in t:
            return True
    return False

def is_disclosure_permission_candidate(t):
    if 'confidential information' not in t:
        return False
    if 'disclos' not in t and 'access' not in t:
        return False
    if 'employee' not in t and 'contractor' not in t:
        return False
    return has_any_phrase(t,['may disclose','may be disclosed','permitted to disclose','restrict access','disclosed only to','except to'])

def is_recipient_definition(t):
    return has_any_phrase(t,['recipient” shall mean','recipient" shall mean','recipient shall mean'])

